icWindow_AC(short windowID, void* wStorage, WindowRef behind)	:	fWMgrWindow(Create(windowID, wStorage, behind)){}CClassicWindow_AC::CClassicWindow_AC(void* wStorage, const Rect& boundsRect, ConstStr255Param title, 									 bool visible, short procID, WindowRef behind, bool goAwayFlag, 									 long refCon)	:	fWMgrWindow(Create(wStorage, boundsRect, title, visible, procID, behind, 						   goAwayFlag, refCon)){}//----------------------------------------------------------------------------------------// Window Creation & Persistence//----------------------------------------------------------------------------------------//----------------------------------------------------------------------------------------// Create//----------------------------------------------------------------------------------------WindowRef CClassicWindow_AC::Create(short windowID, void* wStorage, WindowRef behind){	WindowRef window = GetNewCWindow(windowID, wStorage, behind);	ThrowIfNULL_AC(window);	return window;}WindowRef CClassicWindow_AC::Create(void* wStorage, const Rect& boundsRect, ConstStr255Param title, 									bool visible, short procID, WindowRef behind, bool goAwayFlag, 									long refCon){	WindowRef window = NewCWindow(wStorage, &boundsRect, title, visible, procID, behind, 								  goAwayFlag, refCon);	ThrowIfNULL_AC(window);	return window;}//----------------------------------------------------------------------------------------// Dispose//----------------------------------------------------------------------------------------void CClassicWindow_AC::Dispose(){	if (fWMgrWindow)	{		DisposeWindow(fWMgrWindow);		fWMgrWindow = NULL;	}}#if !qCarbon//----------------------------------------------------------------------------------------// Close//----------------------------------------------------------------------------------------void CClassicWindow_AC::Close(){	MacCloseWindow(fWMgrWindow);}#endif//-----------------