xt(){	if (fCurrent)		fCurrent = fIterateForward ? NextWindow(fCurrent) : PreviousWindow(fCurrent);	return Current();}//----------------------------------------------------------------------------------------// CWindowIterator_AC::FirstWindow://----------------------------------------------------------------------------------------WindowRef CWindowIterator_AC::FirstWindow(){	WindowRef currentWindow = CWindow_AC::GetList();// ••• Should there be an ACS version of gWorkPort?//	if (currentWindow && (currentWindow == gWorkPort))//		currentWindow = NextWindow(currentWindow);	return currentWindow;}//----------------------------------------------------------------------------------------// CWindowIterator_AC::NextWindow://----------------------------------------------------------------------------------------WindowRef CWindowIterator_AC::NextWindow(WindowRef aWindow){	WindowRef currentWindow = GetNextWindow_AC(aWindow);// ••• Should there be an ACS version of gWorkPort?//	while (currentWindow && (currentWindow == gWorkPort))//		// ignore the work window//		currentWindow = GetNextWindow_AC(currentWindow);	return currentWindow;}//----------------------------------------------------------------------------------------// CWindowIterator_AC::PreviousWindow://----------------------------------------------------------------------------------------WindowRef CWindowIterator_AC::PreviousWindow(WindowRef aWindow){	WindowRef currentWindow = FirstWindow();	while (currentWindow && (NextWindow(currentWindow) != aWindow))		currentWindow = NextWindow(currentWindow);	return currentWindow;}//----------------------------------------------------------------------------------------// CWindowIterator_AC::LastWindow://----------------------------------------------------------------------------------------WindowRef CWindowIterator_AC::LastWindow(){	WindowRef currentWindow = FirstWindow();	while (currentWindow && NextWindow(currentWindow))		currentWindow = NextWindow(currentWindow);	return currentWindow;}//========================================================================================// Global Functions//========================================================================================#if qCarbon//----------------------------------------------------------------------------------------// GetWindowZoomFlag//----------------------------------------------------------------------------------------bool GetWindowZoomFlag(WindowRef window)// GetWindowZoomFlag is not available in Carbon, but we can check the equivalent// window feature. {	bool result = false;	UInt32 features;	OSStatus err = ::GetWindowFeatures(window, &features);	if (err == noErr)		result = features && kWindowCanZoom;	// •••  how to check this bit?	return result;}#endif//----------------------------------------------------------------------------------------// End of CWindow_AC.cpp